def pe(exo):
    if exo: path='M20 120 C40 120 55 120 80 90 C100 35 120 30 140 40 C160 55 175 150 205 165 C225 170 240 170 255 170'; y1,y2=120,170
    else: path='M20 170 C40 170 55 170 75 130 C95 40 115 30 140 38 C165 48 180 110 215 120 C235 125 245 125 255 122'; y1,y2=170,122
    return ('<rect x="2" y="2" width="270" height="215" fill="none" stroke="#777"/>'
     f'<path d="{path}" stroke="#c0305a" stroke-width="2.5" fill="none"/>'
     +tx(140,20,'Transition state',10,'middle',700)+tx(20,y1-8,'A + B',10,'start',700)+tx(20,y1+3,'Reactants',8,'start',700)+tx(215,(y2-6),'C + D',10,'start',700)+tx(215,(y2+5),'Products',8,'start',700)
     +'<path d="M132 38 V%d" stroke="#c0305a" stroke-width="1.5"/>'%y1+tx(125,(38+y1)//2,'E<tspan font-size="7" dy="3">a</tspan>',10,'end',700)
     +f'<path d="M60 {y1} H190 M{200 if exo else 215} {y2} H255" stroke="#c0305a" stroke-dasharray="3 3" fill="none"/>'
     +(tx(120,(y1+y2)//2+4,'ΔH',10,'middle',700) if exo else tx(235,(y1+y2)//2+4,'ΔH',10,'middle',700))
     +tx(140,212,'Reaction Progress',10,'middle',700))
s['figures']=[fig(289,'fig9-4a',svg(280,225,'Potential energy diagram of an exothermic reaction: reactants A+B high, products C+D lower, with activation energy and delta H',pe(True)),'Fig. 9.4.A. A potential energy diagram for an exothermic reaction','شکل 9.4.A حرارت خارج کرنے والے تعامل کے لیے مخفی توانائی کا خاکہ','شکل 9.4.A د تودوخه خوشې کوونکي تعامل لپاره د پوټنشیل انرژۍ انځور',[lab('Transition state','عبوری حالت','انتقالي حالت'),lab('A + B Reactants','A + B تعامل کنندگان','A + B متعاملین'),lab('C + D Products','C + D حاصلات','C + D محصولات'),lab('Reaction Progress','تعامل کی پیش رفت','د تعامل پرمختګ')]),
 fig(289,'fig9-4b',svg(280,225,'Potential energy diagram of an endothermic reaction: reactants A+B low, products C+D higher, with activation energy and delta H',pe(False)),'Fig. 9.4.B. A potential energy diagram for an endothermic reaction','شکل 9.4.B گرمی جذب کرنے والے تعامل کے لیے مخفی توانائی کا خاکہ','شکل 9.4.B د تودوخه جذبوونکي تعامل لپاره د پوټنشیل انرژۍ انځور',[lab('Transition state','عبوری حالت','انتقالي حالت'),lab('A + B Reactants','A + B تعامل کنندگان','A + B متعاملین'),lab('C + D Products','C + D حاصلات','C + D محصولات'),lab('Reaction Progress','تعامل کی پیش رفت','د تعامل پرمختګ')])]
